RankInfo *RankInfoStore::getRankInfo(Int rank) const
{
	if (rank >= 1 && rank <= (Int)m_rankInfos.size())
	{
		RankInfo *rankInfo = m_rankInfos[rank - 1];
		if (!rankInfo)
			return NULL;
		return (RankInfo *)rankInfo->friend_getFinalOverride();
	}
	return NULL;
}

